parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "People",
        "Finanzas",
        "Compras",
        "Accesos",
        "Soporte",
        "Proyectos",
        "Administración",
        "Otro"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "Baja",
        "Media",
        "Alta",
        "Crítica"
      ]
    },
    "requester_name": {
      "type": ["string", "null"]
    },
    "requester_email": {
      "type": ["string", "null"],
      "format": "email"
    },
    "client_or_project": {
      "type": ["string", "null"]
    },
    "target_person": {
      "type": ["string", "null"]
    },
    "summary": {
      "type": "string"
    },
    "requested_action": {
      "type": "string"
    },
    "due_date": {
      "type": ["string", "null"],
      "description": "Fecha mencionada explícitamente en el email. Usar formato YYYY-MM-DD solo si puede determinarse con certeza."
    },
    "missing_information": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "suggested_owner": {
      "type": ["string", "null"],
      "description": "Responsable únicamente si surge del email o de reglas externas configuradas."
    },
    "draft_reply": {
      "type": "string"
    },
    "requires_human_approval": {
      "type": "boolean"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    }
  },
  "required": [
    "category",
    "priority",
    "requester_name",
    "requester_email",
    "client_or_project",
    "target_person",
    "summary",
    "requested_action",
    "due_date",
    "missing_information",
    "suggested_owner",
    "draft_reply",
    "requires_human_approval",
    "confidence"
  ]
}

parameters.jsCode:
const aiOutput = $input.item.json.output;
const normalizedData = $('Normalizar Datos').item.json;

const validCategories = ['People', 'Finanzas', 'Compras', 'Accesos', 'Soporte', 'Proyectos', 'Administración', 'Otro'];
const validPriorities = ['Baja', 'Media', 'Alta', 'Crítica'];

const isValid = 
  aiOutput.confidence >= 0.75 &&
  validCategories.includes(aiOutput.category) &&
  validPriorities.includes(aiOutput.priority) &&
  aiOutput.requester_email &&
  aiOutput.missing_information.length === 0;

return {
  ...normalizedData,
  ...aiOutput,
  validation_passed: isValid,
  validation_reason: !isValid ? 
    (aiOutput.confidence < 0.75 ? 'Confianza baja' : 
     aiOutput.missing_information.length > 0 ? 'Información faltante' : 
     'Datos inválidos') : 
    'OK'
};

